## Phase 1 (continued): `chat.js` — Text Renderer + Component Stubs

`chat.js` is imported as a module. `sidebar.js` will import from it. Since `sidebar.js` uses `import { app }` as an ES module, `chat.js` can use standard ES module exports.

### Text Renderer

The parser handles three constructs: triple-backtick code blocks, inline backtick code, and `**bold**`. Newlines become paragraph breaks. Everything else is literal text.

```javascript
// chat.js

/**
 * Parse minimal markdown-like syntax into DOM nodes.
 * Handles: ``` code blocks, `inline code`, **bold**, paragraph breaks.
 * Returns a DocumentFragment ready to append.
 */
export function renderText(rawText) {
  const frag = document.createDocumentFragment();
  const wrapper = document.createElement("div");
  wrapper.className = "sd-text-body";

  // Split on triple-backtick blocks first
  const codeBlockRe = /```(?:\w+)?\n?([\s\S]*?)```/g;
  let lastIndex = 0;
  let match;

  while ((match = codeBlockRe.exec(rawText)) !== null) {
    // Render text before this code block
    if (match.index > lastIndex) {
      _appendInlineText(wrapper, rawText.slice(lastIndex, match.index));
    }
    // Render the code block
    const pre = document.createElement("pre");
    pre.className = "sd-code-block";
    pre.textContent = match[1].trim();
    wrapper.appendChild(pre);
    lastIndex = codeBlockRe.lastIndex;
  }

  // Render remaining text
  if (lastIndex < rawText.length) {
    _appendInlineText(wrapper, rawText.slice(lastIndex));
  }

  frag.appendChild(wrapper);
  return frag;
}

/**
 * Parse inline markup within a text segment (no code blocks).
 * Splits on paragraph breaks (blank lines), then handles inline code + bold.
 */
function _appendInlineText(parent, text) {
  // Collapse multiple blank lines to one paragraph break
  const paragraphs = text.split(/\n{2,}/);

  for (const para of paragraphs) {
    if (!para.trim()) continue;
    const p = document.createElement("p");
    _appendInlineMarkup(p, para.trim());
    parent.appendChild(p);
  }
}

/**
 * Inline parse: `code` and **bold**. Everything else is text.
 */
function _appendInlineMarkup(parent, text) {
  // Token regex: backtick code or bold
  const inlineRe = /(`[^`]+`|\*\*[^*]+\*\*)/g;
  let last = 0;
  let m;

  while ((m = inlineRe.exec(text)) !== null) {
    // Text before token
    if (m.index > last) {
      parent.appendChild(document.createTextNode(text.slice(last, m.index)));
    }
    const token = m[1];
    if (token.startsWith("**")) {
      const strong = document.createElement("strong");
      strong.className = "sd-text-bold";
      strong.textContent = token.slice(2, -2);
      parent.appendChild(strong);
    } else {
      const code = document.createElement("code");
      code.className = "sd-code-inline";
      code.textContent = token.slice(1, -1);
      parent.appendChild(code);
    }
    last = inlineRe.lastIndex;
  }

  // Remaining text
  if (last < text.length) {
    parent.appendChild(document.createTextNode(text.slice(last)));
  }
}
```

Key design choices:
- `renderText` returns a DocumentFragment, not a string — avoids innerHTML entirely (security + correct DOM)
- The regex for code blocks is stateful (`lastIndex`) so it handles multiple blocks per message
- Newline handling: single newlines become text content inside `<p>`, double-newlines become new `<p>` elements — matches the design system's "one blank line between paragraphs" rule
- No DOMParser, no innerHTML, no markdown library

