**`createCollapsibleSection(title, dotColor, count, defaultOpen, buildBody)`**

```javascript
export function createCollapsibleSection(title, dotColor, count, defaultOpen, buildBody) {
  const section = document.createElement("div");
  section.className = "sd-section";

  const trigger = document.createElement("button");
  trigger.className = "sd-section__trigger";
  trigger.type = "button";
  trigger.innerHTML = `
    <span class="sd-section__dot" style="background:${dotColor}"></span>
    <span class="sd-section__title">${title}</span>
    <span class="sd-section__count">${count !== null ? count : ""}</span>
    <span class="sd-section__chevron">&#8250;</span>
  `;

  const body = document.createElement("div");
  body.className = "sd-section__body" + (defaultOpen ? "" : " sd-section__body--collapsed");

  // Lazy build: only call buildBody() once, on first open
  let built = false;
  trigger.addEventListener("click", () => {
    const isCollapsed = body.classList.contains("sd-section__body--collapsed");
    body.classList.toggle("sd-section__body--collapsed");
    trigger.classList.toggle("sd-section__trigger--open");
    if (isCollapsed && !built) {
      built = true;
      buildBody(body);
    }
  });

  // If defaultOpen, build immediately
  if (defaultOpen) {
    built = true;
    buildBody(body);
    trigger.classList.add("sd-section__trigger--open");
  }

  section.appendChild(trigger);
  section.appendChild(body);
  return section;
}
```

The lazy build pattern (only render section body on first expand) matters for large workflow analysis panels — you don't want to build 8 sections' worth of DOM on load.

