`createPanel` builds the header, maps over sections to create collapsible sections with type-appropriate bodies, then adds the footer:

```javascript
export function createPanel(panelData) {
  if (!panelData) return null;

  const panel = document.createElement("div");
  panel.className = "sd-panel";

  // Header
  panel.appendChild(_buildPanelHeader(panelData.header));

  // Sections
  if (panelData.sections) {
    const sectionsWrapper = document.createElement("div");
    sectionsWrapper.className = "sd-panel-sections";
    for (const sec of panelData.sections) {
      sectionsWrapper.appendChild(
        createCollapsibleSection(
          sec.title,
          sec.dotColor,
          sec.count,
          sec.defaultOpen,
          (body) => _buildSectionBody(body, sec)
        )
      );
    }
    panel.appendChild(sectionsWrapper);
  }

  // Footer
  if (panelData.footer) {
    panel.appendChild(createActionFooter(panelData.footer.status, panelData.footer.actions));
  }

  return panel;
}

function _buildSectionBody(body, sec) {
  switch (sec.type) {
    case "flow_chain":
      for (const chain of (sec.data.chains || [])) {
        if (chain.label) {
          const chainLabel = document.createElement("div");
          chainLabel.className = "sd-section-chain-label";
          chainLabel.textContent = chain.label.toUpperCase();
          body.appendChild(chainLabel);
        }
        body.appendChild(createFlowChain(chain.nodes || []));
      }
      break;
    case "slot_tags":
      const tagRow = document.createElement("div");
      tagRow.className = "sd-tag-row";
      for (const t of (sec.data.tags || [])) {
        tagRow.appendChild(createSlotTag(t.label, t.slotType));
      }
      body.appendChild(tagRow);
      for (const d of (sec.data.details || [])) {
        body.appendChild(createDetailRow(d.label, d.value));
      }
      break;
    case "capability_rows":
      for (const cap of (sec.data.capabilities || [])) {
        body.appendChild(createCapabilityRow(cap.label, cap.desc, cap.color));
      }
      break;
    case "detail_rows":
      for (const d of (sec.data.rows || [])) {
        body.appendChild(createDetailRow(d.label, d.value));
      }
      break;
  }
}
```

