            categories["sampler"].append(ct)
        elif any(k in ct_lower for k in ("clip", "encode", "conditioning")):
            categories["clip"].append(ct)
        elif any(k in ct_lower for k in ("vae", "decode")):
            categories["vae"].append(ct)
        elif any(k in ct_lower for k in ("save", "preview", "output", "image")):
