**`_extract_flow_chain`** — produces an ordered list of `{label, slotType}` nodes by following connections from roots (nodes with no inputs) to leaves:

```python
def _extract_flow_chain(nodes: dict, connections: list) -> list:
    """Extract a simplified linear flow chain for display."""
    if not connections:
        return []

    # Build adjacency: node_id -> outgoing target node_ids
    # Find root nodes (no incoming connections)
    has_incoming = set()
    for conn in connections:
        has_incoming.add(conn.get("to_node", ""))

    roots = [nid for nid in nodes if nid not in has_incoming]
    if not roots:
        roots = [sorted(nodes.keys())[0]]  # fallback

    # Simple BFS to get ordered visit sequence (max 8 for display)
    visited = []
    queue = list(roots[:1])  # start from first root only
    seen = set()
    adj = {}
    for conn in connections:
        frm = conn.get("from_node", "")
        to = conn.get("to_node", "")
        adj.setdefault(frm, []).append(to)

    while queue and len(visited) < 8:
        nid = queue.pop(0)
        if nid in seen:
            continue
        seen.add(nid)
        node = nodes.get(nid, {})
        ct = node.get("class_type", "")
        slot = _classify_slot(ct)
        visited.append({"label": ct, "slotType": slot})
        queue.extend(adj.get(nid, []))

    return visited

def _classify_slot(class_type: str) -> str:
    ct = class_type.lower()
    if any(k in ct for k in ("checkpoint", "unet", "model")): return "model"
    if any(k in ct for k in ("clip", "conditioning")): return "clip"
    if any(k in ct for k in ("sample", "ksampler")): return "sampler"
    if any(k in ct for k in ("vae", "decode")): return "vae"
    if any(k in ct for k in ("image", "save", "output")): return "image"
    if any(k in ct for k in ("latent",)): return "latent"
    return "other"
```

