### Discovery Panel (`_panel_discovery`)

The `discover` tool returns `{"results": [...], "query": "...", "source": "..."}`. Each result has `name`, `description`, `type`, `installed`. Panel maps to a discovery result layout:

```python
def _panel_discovery(result: dict, tool_input: dict) -> dict | None:
    results = result.get("results", [])
    if not results:
        return None

    query = tool_input.get("query", "")
    top = results[0]

    sections = []
    for r in results[:5]:  # max 5 results
        tags = [{"label": r["name"], "slotType": _type_to_slot(r.get("type", ""))}]
        details = []
        if r.get("description"):
            details.append({"label": "About", "value": r["description"][:60]})
        if "installed" in r:
            details.append({"label": "Status", "value": "installed" if r["installed"] else "available"})
        sections.append({
            "title": r["name"],
            "dotColor": _type_to_color(r.get("type", "")),
            "count": None,
            "defaultOpen": False,
            "type": "slot_tags",
            "data": {"tags": tags, "details": details},
        })

    return {
        "type": "discovery",
        "header": {
            "label": "discovery  ·  results",
            "badge": str(len(results)),
            "title": query or "Search results",
            "summary": top.get("description", "")[:120],
            "stats": [{"value": str(len(results)), "label": "found"}],
        },
        "sections": sections,
        "footer": {
            "status": f"{len(results)} results",
            "actions": [{"label": "Install", "variant": "primary"}],
        },
    }
```

